class Database extends CI_Controller
{
    private $_pageData = [];
    function __construct()
    {
        parent::__construct();
        $this->initializePageData();
        define('MODULE','Config');
        $this->_ci_ob_level  = ob_get_level();

        //         // Default
        $this->_ci_view_paths = array(
            APPPATH . 'controllers/'.MODULE => TRUE
        );
    }
    function getMessage($cause){

        $causeArray = [];
        $return = $this->session->flashdata($cause);

        if($return == ''){
            $causeArray = [];
        }else{
            $causeArray = json_decode($return);
        }
        return $causeArray;
    }

    public function Install($forceFully = false){

        echo 'Collecting Key'.'<br/>';
        $key = $this->getMessage('destructionKey');
        echo 'Key Collected'.'<br/>';
        echo 'Validating Key'.'<br/>';
        if(in_array($_POST['keyToTerminate'],$key)) {
            echo 'Have You requested Force reset?'.'<br/>';
            if ($forceFully === '-f') {
                echo 'Yes!'.'<br/>';
                $mysqli = new mysqli($this->db->hostname, $this->db->username, $this->db->password, $this->db->database);
                $mysqli->query('SET foreign_key_checks = 0');
                if ($result = $mysqli->query("SHOW TABLES")) {
                    while ($row = $result->fetch_array(MYSQLI_NUM)) {
                    $mysqli->query('DROP TABLE IF EXISTS '.$row[0]);
                    }
                }

                $mysqli->query('SET foreign_key_checks = 1');

                $mysqli->close();
            }else {
                echo 'No' . '<br/>';
            }
        }else{

            echo 'Key Not Validated'.'<br/>';

        }
    }

    public function runMigrations(){
        echo 'Scanning Migrations';
        $scanFolder = __DIR__.'../../../../controllers/';
        $orignalLocation = __DIR__.'../../../../migrations/';
        $files = glob($scanFolder.'*');

        $options1 = [];
        $constants = [];
        echo 'Collecting Migrations';
        foreach($files as $file) {
            //do your work here
            if(is_dir($file)){
                $foldername = basename ($file);
                $migrationsFolder = $scanFolder.$foldername.'/migrations/';
                if(is_dir($migrationsFolder)){
                    $this->recurse_copy($migrationsFolder,$orignalLocation);
                }


            }
        }
        echo 'Executing Migrations';
        $mysqli = new mysqli($this->db->hostname, $this->db->username, $this->db->password, $this->db->database);
        $mysqli->query('TRUNCATE TABLE `migrations`');
        $mysqli->close();

        $this->load->library("migration");
        echo 'Executing Migrations';
        if(!$this->migration->current()){
            show_error($this->migration->error_string());
        }else{
            echo 'Migrations Imported';
        }
        echo 'Generating Pre Req Data';
        $this->createAdministrator();


    }

    protected function recurse_copy($src,$dst) {
        $dir = opendir($src);

        @mkdir($dst);
        while(false !== ( $file = readdir($dir)) ) {
            if (( $file != '.' ) && ( $file != '..' )) {
                if ( is_dir($src . '/' . $file) ) {
                    $this->recurse_copy($src . '/' . $file,$dst . '/' . $file);
                }
                else {
                    copy($src . '/' . $file,$dst . '/' . $file);
                }
            }
        }
        closedir($dir);
    }

    protected function createAdministrator(){
        $groupID = $this->aauth->create_group('Admin','The Administrator Group of application.');
        $userID = $this->aauth->create_user(
            $this->_pageData['business_contact_email'],
            $this->_pageData['referenceKey'],
            $this->_pageData['business_contact_name']
        );
        $this->aauth->update_user_custom($userID, ['is_super_admin' => 1, 'change_password' => 1]);

        $this->aauth->add_member($userID,$groupID);

    }

    protected function initializePageData(){

        if(!file_exists(__DIR__ . '/../../../../licence.bin')){
            redirect('Config/LicenceKey');
        }else{

            $options = [];
            $licenceInfo = unserialize(file_get_contents(__DIR__ . '/../../../../licence.bin'));

            foreach ($licenceInfo as $parent=>$row){
                if(is_object($row) || is_array($row)){
                    foreach($row as $key=>$val){

                        define($parent.'_'.$key, $val);
                        $options[$parent.'_'.$key] = $val;

                    }
                }else{
                    define($parent, $val);
                    $options[$parent] = $row;
                }

            }
            //If Configured on Server then These Will be missed.
            $defaultImage = 'data:image/jpg;base64,';
            $appImage = $defaultImage;
            $printImage = $defaultImage;
            $mustKeys = [
                'OPEN_ENTRY_POINT' => 0,
                'OPEN_ENTRY_POINT_LINK' => 'Tablet/LoadView',
                'OPEN_ENTRY_POINT_TITLE' => 'Tablet',
            ];
            foreach ($mustKeys as $key => $val) {

                if (!array_key_exists($key, $options)) {
                    $options[$key] = $val;
                    define($key, $val);
                }
            }

            $mustKeys = [
                'BUSINESS_LOGO_IMAGE_64' => $defaultImage,
                'APP_LOGO_IMAGE_64' => $appImage,
                'PRINT_IMAGE_64' => $printImage
            ];
            foreach ($mustKeys as $key => $val) {

                if (!array_key_exists($key, $options)) {
                    $options[$key] = $val;
                }
            }



            $this->_pageData = $options;


        }
    }

}